-- Original SDK example. WAVs are generated by the creator's audio template.
local started, phase = 0, 0
return {
    api = 1,
    audio_api = 1,
    on_start = function(event)
        started, phase = event.tick, 0
        game.audio.play(0, 0x00000001, 1, 0.25, false)
        game.message("Audio lab: one-shot")
    end,
    on_tick = function(event)
        local seconds = (event.tick - started) / event.tick_rate
        if phase == 0 and seconds >= 1 then
            game.audio.play(1, 0x00000002, 1, 0.2, true)
            game.message("Audio lab: loop")
            phase = 1
        end
        if phase == 1 and seconds >= 2 then
            game.audio.pause(1, true)
            game.message("Audio lab: paused")
            phase = 2
        end
        if phase == 2 and seconds >= 3 then
            game.audio.pause(1, false)
            game.audio.pitch(1, 0.5)
            game.message("Audio lab: resumed at half pitch")
            phase = 3
        end
        if phase == 3 and seconds >= 4 then
            game.audio.volume(1, 0.05)
            game.message("Audio lab: quieter")
            phase = 4
        end
        if phase == 4 and seconds >= 5 then
            game.audio.stop_all()
            game.message("Audio lab: stopped")
            phase = 5
        end
    end,
    on_stop = function() game.audio.stop_all() end,
}
